WEBD_HELP = [
    "# webdeep - الويب العميق: أطر وخوادم وبروتوكولات (fastapi / starlette / tornado / websockets)",
]

_WEBD_TOKEN = re.compile(
    r"(?P<dot>\.)?"
    r"(?P<word>(?!\d)[\w\u064B-\u065F\u0670]+)"
    r"(?P<open>\s*\()?"
)

USER_NAMES = set()


def _webdeep_replace(match):
    dot = match.group("dot")
    word = match.group("word")
    open_paren = match.group("open")
    if word in USER_NAMES:
        return match.group(0)
    if dot:
        return match.group(0)
    if word in WEBD_CONSTS:
        return WEBD_CONSTS[word]
    if word in WEBD_FUNCS:
        return WEBD_FUNCS[word] + (open_paren or "")
    return match.group(0)


def WEBD_SUBSTITUTE(text):
    """يترجم كلمات المكتبة في نص واحد ويُرجع المترجم."""
    if not text:
        return text
    return _WEBD_TOKEN.sub(_webdeep_replace, text)
